def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] != 0}

    # The three L orientations in the demonstrations, labeled by color.
    # The omitted corner is respectively top-left, top-right, or bottom-left.
    l_shapes = [
        ({(0, 1), (1, 0), (1, 1)}, 2),
        ({(0, 0), (1, 0), (1, 1)}, 4),
        ({(0, 0), (0, 1), (1, 1)}, 3),
    ]

    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if square <= occupied:
                pieces.append((square, 1, r, c))
            for shape, color in l_shapes:
                cells = {(r + dr, c + dc) for dr, dc in shape}
                if cells <= occupied:
                    pieces.append((cells, color, r, c))

    by_cell = {cell: [] for cell in occupied}
    for piece in pieces:
        for cell in piece[0]:
            by_cell[cell].append(piece)

    # Prefer a full square when choosing among otherwise equivalent tilings.
    for cell in by_cell:
        by_cell[cell].sort(key=lambda p: (p[1] != 1, p[2], p[3], p[1]))

    def search(remaining, chosen):
        if not remaining:
            return chosen

        cell, options = min(
            ((cell, [p for p in by_cell[cell] if p[0] <= remaining])
             for cell in remaining),
            key=lambda item: len(item[1])
        )
        for piece in options:
            result = search(remaining - piece[0], chosen + [piece])
            if result is not None:
                return result
        return None

    solution = search(occupied, [])
    if solution is None:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    for cells, color, _, _ in solution:
        for r, c in cells:
            out[r][c] = color
    return out
